#!/bin/bash
sed -i 's/import androidx.compose.ui.Modifier/import androidx.compose.ui.Modifier\nimport android.os.Build\nimport android.Manifest\nimport com.google.accompanist.permissions.ExperimentalPermissionsApi\nimport com.google.accompanist.permissions.isGranted\nimport com.google.accompanist.permissions.rememberPermissionState\nimport androidx.compose.runtime.LaunchedEffect/g' app/src/main/java/com/example/MainActivity.kt

sed -i 's/OtakuHubAppTheme {/OtakuHubAppTheme {\n                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {\n                        @OptIn(ExperimentalPermissionsApi::class)\n                        val notificationPermissionState = rememberPermissionState(\n                            Manifest.permission.POST_NOTIFICATIONS\n                        )\n                        LaunchedEffect(Unit) {\n                            if (!notificationPermissionState.status.isGranted) {\n                                notificationPermissionState.launchPermissionRequest()\n                            }\n                        }\n                    }/g' app/src/main/java/com/example/MainActivity.kt
